"use strict";
// tests/unit/fortune-sources.test.js — owner order 2026-11-12, Part B: fortune pages and readings show no source
// citations (book / author / tradition / "sources" lists / footnote links) to users in Thai, English or Chinese. The
// sources stay in the knowledge bases and are listed in the back office (admin.html, fortune-sources.js) and in
// docs/FORTUNE-SOURCES.md (both generated by tools/fortune-sources.mjs). Non-fortune pages keep their sources.
const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const vm = require("node:vm");
const { execFileSync } = require("node:child_process");

const ROOT = path.join(__dirname, "..", "..");
const read = f => fs.readFileSync(path.join(ROOT, f), "utf8");
for (const f of fs.readdirSync(path.join(ROOT, "i18n")).filter(f => /^(?:zh|en)-kb-.+\.js$/.test(f))) require(path.join(ROOT, "i18n", f));
const FA = require("../../fortune-ai.js");

const FORTUNE_PAGES = ["fortune", "faceread", "palm", "horoscope", "tarot", "iching", "bazi", "taksa", "lek7", "numbers", "fengshui", "dream",
  "zodiac", "astro", "lifegraph", "planner", "luckycolor", "report"].map(p => p + ".html");
const KBS = ["astro-kb.js", "dream-kb.js", "fengshui-kb.js", "faceread-kb.js", "horoscope-kb.js", "iching-kb.js", "numbers-kb.js", "palm-kb.js", "tarot-kb.js", "zodiac-kb.js"];
const ALL_SOURCES = KBS.flatMap(f => { const K = require(path.join(ROOT, f)); return (K.sources || []).concat(K.readingSources || []); });
// ordinary words that are also a source's short name (their URL hosts are still checked)
const GENERIC = new Set(["Central", "All About", "China Travel"]);
// who / what each source is: the part of the label before " — " (site, author or book), plus every URL host
const NAMES = [...new Set(ALL_SOURCES.flatMap(s => [String(s.label).split(" — ")[0].trim(), new URL(s.url).hostname.replace(/^www\./, "")]))].filter(n => n.length >= 3 && !GENERIC.has(n));
// heading / footnote words of a citation block in the three languages
const CITE_WORDS = /แหล่งอ้างอิง|อ้างอิงจาก|บรรณานุกรม|ที่มา:|\b(?:References?|Sources?:|Bibliography|Cited|Citation)\b|参考资料|参考文献|出处|来源[:：]/;

function dict(lang) {
  const w = {}; w.window = w;
  for (const f of fs.readdirSync(path.join(ROOT, "i18n")).filter(f => f.startsWith(lang + "-") && f.endsWith(".js"))) vm.runInNewContext(read("i18n/" + f), w, { filename: f });
  const out = {};
  for (const q of w.LQI18N_Q || []) Object.assign(out, q[lang] || {});
  for (const k of Object.keys(w)) if (k !== "window" && w[k] && typeof w[k] === "object" && !Array.isArray(w[k]) && w[k][lang] && typeof w[k][lang] === "object") Object.assign(out, w[k][lang]);
  return out;
}

test("fortune pages: no sources heading, no citation list, no source link, no source name (TH page text + EN/ZH dictionary values)", () => {
  const en = dict("en"), zh = dict("zh");
  let keys = 0;
  for (const p of FORTUNE_PAGES) {
    const html = read(p), body = html.replace(/<head>[\s\S]*?<\/head>/, "").replace(/<script[\s\S]*?<\/script>/g, "");
    assert.ok(!/data-i18n="fortune\.common\.sources"/.test(html), p + ": sources heading");
    assert.ok(!/id="\w+Sources"/.test(html), p + ": citation list element");
    assert.ok(!CITE_WORDS.test(body), p + ": citation words: " + (body.match(CITE_WORDS) || [])[0]);
    for (const s of ALL_SOURCES) assert.ok(!body.includes(s.url), p + ": links " + s.url);
    for (const n of NAMES) assert.ok(!body.includes(n), p + ": names source " + n);
    for (const m of body.matchAll(/data-i18n="([^"]+)"/g)) {
      keys++;
      for (const [lang, D] of [["en", en], ["zh", zh]]) {
        const v = String(D[m[1]] || "");
        assert.ok(!CITE_WORDS.test(v), `${p} ${lang} ${m[1]}: ${v.slice(0, 60)}`);
        for (const n of NAMES) assert.ok(!v.includes(n), `${p} ${lang} ${m[1]} names source ${n}`);
      }
    }
  }
  assert.ok(keys > 300, "keys checked: " + keys);
});

test("fortune page scripts no longer render KB.sources (the data stays in the knowledge bases)", () => {
  for (const f of ["astro.js", "dream.js", "fengshui.js", "faceread.js", "horoscope.js", "iching.js", "numbers.js", "palm.js", "tarot.js", "zodiac.js", "lifecal-ui.js",
    "lensiq-planner.js", "lensiq-luckycolor.js", "report.js", "lensiq-report.js", "fortune-kit.js", "fortune-ai.js"]) {
    const s = read(f);
    assert.ok(!/\b(?:KB|K)\.(?:sources|readingSources)\b/.test(s), f + " renders the source list");
    assert.ok(!/#\w+Sources\b/.test(s), f + " writes a sources element");
  }
  assert.ok(ALL_SOURCES.length >= 80, "sources kept in the knowledge bases: " + ALL_SOURCES.length);
});

test("readings: every domain × TH/EN/ZH × 4 fact sets × 2 seeds names no source (labels, sites, authors, URLs)", async () => {
  const X = await import("../../tools/fortune-review-export.mjs");
  let n = 0;
  for (const d of X.DOMAINS) {
    const r = X.lcg(77 + d.length * 13);
    for (let i = 0; i < 4; i++) {
      const facts = X.factsFor(d, i, r);
      for (const lang of ["th", "en", "zh"]) for (const seed of [11 + i, 9001 + i]) {
        const res = FA.compose(facts, { seed, lang });
        const why = res.why && res.why.lines ? res.why.lines.map(l => l.k + " " + l.t).join("\n") : "";
        const t = X.readingText(res) + "\n" + why + "\n" + (res.note || "");
        n++;
        assert.ok(!/https?:\/\//.test(t), `${d}/${lang}: URL in reading`);
        assert.ok(!CITE_WORDS.test(t), `${d}/${lang}: citation words: ${(t.match(CITE_WORDS) || [])[0]}`);
        for (const nm of NAMES) assert.ok(!t.includes(nm), `${d}/${lang}: names source ${nm}`);
      }
    }
  }
  assert.equal(n, 15 * 4 * 3 * 2);
});

test("back office and docs still list every source: generated files are current; admin loads and renders them; the Worker serves them", () => {
  execFileSync(process.execPath, [path.join(ROOT, "tools", "fortune-sources.mjs"), "--check"], { stdio: "pipe" });
  const md = read("docs/FORTUNE-SOURCES.md"), js = read("fortune-sources.js");
  for (const s of ALL_SOURCES) { assert.ok(md.includes(s.url), "docs miss " + s.url); assert.ok(js.includes(JSON.stringify(s.url)), "admin data misses " + s.url); }
  const w = {}; w.window = w; vm.runInNewContext(js, w);
  assert.equal(w.LQ_FORTUNE_SOURCES.reduce((a, d) => a + d.sources.length, 0), ALL_SOURCES.length);
  const html = read("admin.html");
  assert.match(html, /<script src="fortune-sources\.js\?v=\d+"><\/script>\s*<script src="admin\.js/);
  assert.match(html, /data-tab="fsources"/);
  assert.match(html, /data-panel="fsources"[\s\S]*id="adFsrc"/);
  assert.match(read("admin.js"), /loaders\.fsources = function[\s\S]*LQ_FORTUNE_SOURCES/);
  assert.match(read("backend/scripts/build-admin.mjs"), /"fortune-sources\.js"/);
  assert.match(read("backend/src/index.js"), /"\/fortune-sources\.js"/);
  for (const k of ["adf.tab", "adf.h", "adf.p", "adf.none"]) { assert.ok(dict("en")[k], "en " + k); assert.ok(dict("zh")[k], "zh " + k); }
});

test("non-fortune pages keep their sources: medicine, product check, category accuracy sources", () => {
  const med = read("medicine.html");
  assert.match(med, /data-i18n="md\.ab\.h">แหล่งข้อมูลและข้อจำกัด</);
  assert.match(med, /National Librar/);
  assert.match(read("lensiq-pc-ui.js"), /แหล่งข้อมูลทางการ/);
  for (const c of ["cat-fortune.html", "cat-health.html", "cat-security.html"]) assert.match(read(c), /data-i18n="cat\.src\.h">ที่มาของตัวเลข</, c);
});
